Copy the following pipeline, paste it into the editor, and replace the `PROMETHEUS_REMOTE_WRITE_URL` and `METRICS_USERNAME` placeholders with your own values. To find both values, sign in to your [Grafana Cloud Portal](https://grafana.com/docs/grafana-cloud/platform/security-and-account-management/account-management/cloud-stacks/), select your stack, and click **Details** in the **Prometheus** section. The **Remote Write Endpoint** section lists the URL and the username.

```alloy
prometheus.exporter.unix "default" { }

prometheus.scrape "default" {
  targets    = prometheus.exporter.unix.default.targets
  forward_to = [prometheus.relabel.team.receiver]
  job_name   = "integrations/node_exporter"
}

prometheus.relabel "team" {
  forward_to = [prometheus.remote_write.grafana_cloud.receiver]

  rule {
    action       = "replace"
    target_label = "team"
    replacement  = argument.attributes.value["team"]
  }
}

prometheus.remote_write "grafana_cloud" {
  endpoint {
    url = "PROMETHEUS_REMOTE_WRITE_URL"

    basic_auth {
      username = "METRICS_USERNAME"
      password = sys.env("GCLOUD_RW_API_KEY")
    }
  }
}
```
